  | "missing-owner"
  | "missing-ttl"
  | "expired"
  | "conflict"
  | "invalid-kind";

export interface CheckpointAttachmentBinding {
  attachmentRef: string;
  kind: CheckpointAttachmentKind | string;
  contentHash: string;
  owner: string;
  ttlExpiresAt: string | number;
}

export interface CheckpointAttachmentBindingInput {
  attachmentRef: string;
  kind: CheckpointAttachmentKind | string;
  contentHash?: string | null;
  owner?: string | null;
  ttlExpiresAt?: string | number | null;
  ttlSeconds?: number | null;
}

export interface CheckpointAttachmentRecoveryState {
  status: CheckpointAttachmentBindingStatus;
  attachmentRef: string;
  kind: CheckpointAttachmentKind | string;
  contentHash?: string;
  owner?: string;
  ttlExpiresAt?: string;
  reason?: string;
}

export interface RecoveredCheckpointAttachment {
  attachmentRef: string;
  kind: CheckpointAttachmentKind;
  contentHash: string;
  owner: string;
  ttlExpiresAt: string;
}

export interface CheckpointAttachmentRecoveryResult {
  recovered: RecoveredCheckpointAttachment[];
  states: CheckpointAttachmentRecoveryState[];
  digest: string;
}

export interface RecoverCheckpointAttachmentBindingsOptions {
  /** Evaluation time for relative TTLs. Supplying it keeps recovery deterministic. */
  evaluatedAtMs?: number;
}

const SHA256_HEX = /^[0-9a-fA-F]{64}$/;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function asNonEmptyString(value: unknown): string | undefined {
  return typeof value === "string" && value.trim().length > 0 ? value : undefined;
}

function normalizeHash(value: unknown): string | undefined {
  return typeof value === "string" && SHA256_HEX.test(value)
    ? value.toLowerCase()
    : undefined;
}

function normalizeExpiry(
  input: CheckpointAttachmentBindingInput,
  evaluatedAtMs: number,
): { value: string } | { error: "missing-ttl" | "expired" } {
  if (input.ttlExpiresAt !== undefined && input.ttlExpiresAt !== null) {
    const raw =
      typeof input.ttlExpiresAt === "number"
        ? input.ttlExpiresAt
        : Date.parse(String(input.ttlExpiresAt));
    if (!Number.isFinite(raw)) {
      return { error: "missing-ttl" };
    }
    if (raw <= evaluatedAtMs) {
      return { error: "expired" };
    }
    return { value: new Date(raw).toISOString() };
  }

  if (typeof input.ttlSeconds === "number" && Number.isFinite(input.ttlSeconds)) {
    if (input.ttlSeconds <= 0) {
      return { error: "expired" };
    }
    return {
      value: new Date(evaluatedAtMs + input.ttlSeconds * 1000).toISOString(),
    };
  }

  return { error: "missing-ttl" };
}

function isAllowedKind(value: unknown): value is CheckpointAttachmentKind {
  return (
    typeof value === "string" &&
    (CHECKPOINT_ATTACHMENT_KINDS as readonly string[]).includes(value)
  );
}

function canonicalJson(value: unknown): string {
  if (value === null || typeof value !== "object") {
    return JSON.stringify(value);
  }
  if (Array.isArray(value)) {
    return `[${value.map(canonicalJson).join(",")}]`;
  }
  const record = value as Record<string, unknown>;
  const entries = Object.keys(record)
    .sort()
    .map((key) => `${JSON.stringify(key)}:${canonicalJson(record[key])}`);
  return `{${entries.join(",")}}`;
}

function sha256(value: string): string {
  return createHash("sha256").update(value, "utf8").digest("hex");
}

function compareText(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

function compareRecovered(
  left: RecoveredCheckpointAttachment,
  right: RecoveredCheckpointAttachment,
): number {
  return (
    compareText(left.attachmentRef, right.attachmentRef) ||
    compareText(left.kind, right.kind) ||
    compareText(left.contentHash, right.contentHash) ||
    compareText(left.owner, right.owner) ||
    compareText(left.ttlExpiresAt, right.ttlExpiresAt)
  );
}

function compareState(
  left: CheckpointAttachmentRecoveryState,
  right: CheckpointAttachmentRecoveryState,
): number {
  return (
    compareText(left.attachmentRef, right.attachmentRef) ||
    compareText(left.kind, right.kind) ||
    compareText(left.status, right.status) ||
    compareText(left.contentHash ?? "", right.contentHash ?? "") ||
    compareText(left.owner ?? "", right.owner ?? "") ||
    compareText(left.ttlExpiresAt ?? "", right.ttlExpiresAt ?? "")
  );
}

/**
 * Validates and recovers checkpoint attachment bindings without mutating its input.
 * The first occurrence of an attachmentRef wins. A later occurrence with a
 * different valid content hash is reported as conflict; identical occurrences
 * are de-duplicated.
 */
export function recoverCheckpointAttachmentBindings(
  input:
    | readonly CheckpointAttachmentBindingInput[]
    | { bindings?: readonly CheckpointAttachmentBindingInput[] },
  options: RecoverCheckpointAttachmentBindingsOptions = {},
): CheckpointAttachmentRecoveryResult {
  const bindings = Array.isArray(input)
    ? input
    : isRecord(input) && Array.isArray(input.bindings)
      ? input.bindings
      : [];
  const evaluatedAtMs = options.evaluatedAtMs ?? 0;
  const states: CheckpointAttachmentRecoveryState[] = [];
  const recovered: RecoveredCheckpointAttachment[] = [];
  const firstByRef = new Map<string, { hash?: string; binding?: RecoveredCheckpointAttachment }>();
  const recoveredKeys = new Set<string>();

  for (const candidate of bindings) {
    const attachmentRef = asNonEmptyString(candidate?.attachmentRef) ?? "";
    const kind = candidate?.kind ?? "";
    const rawOwner = asNonEmptyString(candidate?.owner);
    const rawHash = candidate?.contentHash;
    const normalizedHash = normalizeHash(rawHash);
    const base: CheckpointAttachmentRecoveryState = {
      status: "recovered",
      attachmentRef,
      kind,
    };

    if (!isAllowedKind(kind)) {
      states.push({ ...base, status: "invalid-kind", reason: "unsupported attachment kind" });
      continue;
    }

    if (rawHash === undefined || rawHash === null || rawHash === "") {
      states.push({ ...base, status: "missing-content-hash" });
      continue;
    }
    if (!normalizedHash) {
      states.push({ ...base, status: "invalid-content-hash" });
      continue;
    }

    const prior = firstByRef.get(attachmentRef);
    if (prior) {
      if (prior.hash === normalizedHash) {
        continue;
      }
      states.push({
        ...base,
        status: "conflict",
        contentHash: normalizedHash,
        owner: rawOwner,
        reason: "attachmentRef is already bound to a different content hash",
      });
      continue;
    }

    const expiry = normalizeExpiry(candidate, evaluatedAtMs);
    if ("error" in expiry) {
      states.push({
        ...base,
        status: expiry.error,
        contentHash: normalizedHash,
        owner: rawOwner,
      });
      firstByRef.set(attachmentRef, { hash: normalizedHash });
      continue;
    }
    if (!rawOwner) {
      states.push({
        ...base,
        status: "missing-owner",
        contentHash: normalizedHash,
        ttlExpiresAt: expiry.value,
      });
      firstByRef.set(attachmentRef, { hash: normalizedHash });
      continue;
    }

    const binding: RecoveredCheckpointAttachment = {
      attachmentRef,
      kind,
      contentHash: normalizedHash,
      owner: rawOwner,
      ttlExpiresAt: expiry.value,
    };
    firstByRef.set(attachmentRef, { hash: normalizedHash, binding });
    const key = `${attachmentRef}\u0000${normalizedHash}`;
    if (!recoveredKeys.has(key)) {
      recoveredKeys.add(key);
      recovered.push(binding);
    }
    states.push({ ...base, ...binding });
  }

  recovered.sort(compareRecovered);
  states.sort(compareState);
  const digest = sha256(canonicalJson(recovered));
  return { recovered, states, digest };
}

export const recoverAttachmentBindings = recoverCheckpointAttachmentBindings;

export default recoverCheckpointAttachmentBindings;
